// MARK: - medication alarm, snoozed

/// Same name and shape as the type the app schedules alarms with (modules/crohnic-alarm),
/// so the system pairs the alarm with this Live Activity.
@available(iOS 26.0, *)
struct CrohnicAlarmMetadata: AlarmMetadata {
  var title: String?
}

@available(iOS 26.0, *)
struct CrohnicAlarmTimer: View {
  let state: AlarmPresentationState

  var body: some View {
    switch state.mode {
    case .countdown(let info):
      Text(info.fireDate, style: .timer)
    default:
      Text("İlaç")
    }
  }
}

@available(iOS 26.0, *)
struct CrohnicAlarmLockScreen: View {
  let context: ActivityViewContext<AlarmAttributes<CrohnicAlarmMetadata>>

  var body: some View {
    HStack(spacing: 12) {
      Image(systemName: "pills.fill")
        .font(.title2)
        .foregroundStyle(context.attributes.tintColor)
      VStack(alignment: .leading, spacing: 2) {
        Text(context.attributes.metadata?.title ?? "İlaç")
          .font(.headline)
          .lineLimit(1)
        Text("Ertelendi, birazdan yeniden çalacak")
          .font(.subheadline)
          .foregroundStyle(.secondary)
          .lineLimit(1)
      }
      Spacer()
      CrohnicAlarmTimer(state: context.state)
        .font(.title2.monospacedDigit().bold())
    }
    .padding()
  }
}

@available(iOS 26.0, *)
struct CrohnicAlarmLiveActivity: Widget {
  var body: some WidgetConfiguration {
    ActivityConfiguration(for: AlarmAttributes<CrohnicAlarmMetadata>.self) { context in
      CrohnicAlarmLockScreen(context: context)
    } dynamicIsland: { context in
      DynamicIsland {
        DynamicIslandExpandedRegion(.leading) {
          Image(systemName: "pills.fill")
            .font(.title2)
            .foregroundStyle(context.attributes.tintColor)
        }
        DynamicIslandExpandedRegion(.trailing) {
          CrohnicAlarmTimer(state: context.state)
            .font(.title3.monospacedDigit())
        }
        DynamicIslandExpandedRegion(.center) {
          Text(context.attributes.metadata?.title ?? "İlaç")
            .font(.headline)
            .lineLimit(1)
        }
      } compactLeading: {
        Image(systemName: "pills.fill")
          .foregroundStyle(context.attributes.tintColor)
      } compactTrailing: {
        CrohnicAlarmTimer(state: context.state)
          .monospacedDigit()
          .frame(maxWidth: 48)
      } minimal: {
        Image(systemName: "pills.fill")
          .foregroundStyle(context.attributes.tintColor)
      }
    }
  }
}

// MARK: - bundle
// (kept to a few entries per bundle body, like expo-widgets does, nesting the rest)

@available(iOS 18.0, *)
struct CrohnicControls: WidgetBundle {
  var body: some Widget {
    CrohnicToiletControl()
    CrohnicMealControl()
    CrohnicSymptomControl()
    CrohnicMoreControls().body
  }
}

@available(iOS 18.0, *)
struct CrohnicMoreControls: WidgetBundle {
  var body: some Widget {
    CrohnicMedsControl()
    CrohnicAskControl()
  }
}

struct CrohnicExtras: WidgetBundle {
  var body: some Widget {
    if #available(iOS 18.0, *) {
      CrohnicControls().body
    }
    if #available(iOS 26.0, *) {
      CrohnicAlarmLiveActivity()
    }
  }
}
